function XUiPBRSettlement:OnStart(stageId, settleData, isWin)
    self.StageId = stageId
    self.SettleData = settleData
    
    -- 标题
    if self.ImgGroupStateCtrl then
        self.ImgGroupStateCtrl:ChangeState(isWin and StateType.Success or StateType.Fail)
    end
    
    local stageName = self._Control:GetStageNameById(self.StageId)
    local stageFullName = XUiHelper.FormatTextEx(self._Control:GetClientPBRText('SettleStageNameDesc'), stageName)
    
    for i = 1, 2 do
        local txt = self["TxtTitle" .. i]

        if txt then
            txt.text = stageFullName
        end
    end
    
    -- 展示基础信息
    self.PanelData:RefreshShow(stageId, settleData)

    local itemDict = self._Control.InGameControl:GetItemIdsFromItemDatasByType(settleData.Items, true)
    
    -- 分别展示道具和技能列表
    self.PanelSkill:RefreshItemShow(itemDict[XMVCA.XPBRGame.EnumConst.ItemType.Skill])
    self.PanelProp:RefreshItemShow(itemDict[XMVCA.XPBRGame.EnumConst.ItemType.Other])
    
    -- 角色等级
    self.TxtLevel.text = XUiHelper.FormatTextEx(self._Control:GetClientPBRText('RoleLevelFormat'), self.SettleData.CharacterLevel)

    ---@type XUiPBRSettlementUiPBRPanelAttribute
    self.UiPBRPanelAttribute = XUiPBRSettlementUiPBRPanelAttribute.New(self.UiPBRPanelAttribute, self, self.SettleData.CharacterId, self.SettleData.CurAttrs, self.SettleData.MaxAttrs)
    
    -- 生成模型
    local cfg = self._Control.CharacterControl:GetCharacterCfg(self.SettleData.CharacterId)
    if cfg then
        self.RoleModel:InitShowCharacter(cfg.CuteModelName)
        
        -- 播放动画
        local animName = nil

        if isWin then
            animName = self._Control.CharacterControl:GetCharacterWinActionById(self.SettleData.CharacterId)
        else
            animName = self._Control.CharacterControl:GetCharacterFailActionById(self.SettleData.CharacterId)
        end

        if not string.IsNilOrEmpty(animName) then
            self.RoleModel:PlayRoleAnimation(animName)
        end
    end
    
    self.RoleModel:RefreshShowBySettle(isWin)

    -- 判断是否开启连战
    local hasValidNextStage, nextStageId = self._Control:CheckNextStageExistAndUnlockByStageId(self.StageId)
    local isCanNext = hasValidNextStage and isWin

    self.BtnAgain.gameObject:SetActiveEx(not isCanNext)
    self.BtnNext.gameObject:SetActiveEx(isCanNext)
    
    self.NextStageId = nextStageId
end

